const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // El Escondido area, Ensenada, Baja California
    const fireLocation = ee.Geometry.Point([-116.6, 31.8]);

    // 50 km westward buffer over Pacific Ocean
    const westernExtent = ee.Geometry.Point([-117.05, 31.8]); // ~50km west
    const studyArea = ee.Geometry.Rectangle([-117.2, 31.6, -116.4, 32.0]);

    // January 23, 2025 (local time ~1:44 pm = ~21:44 UTC approximately)
    const targetDate = '2025-01-23';

    // 2. Data Acquisition & Check
    // Try Sentinel-2 first (better spatial resolution)
    let collection = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
      .filterBounds(fireLocation)
      .filterDate('2025-01-23', '2025-01-24')
      .sort('system:time_start');

    let size = await collection.size().getInfo();
    console.log(`Sentinel-2 images found: ${size}`);

    // If no Sentinel-2, try Landsat 8/9
    if (size === 0) {
      collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
        .filterBounds(fireLocation)
        .filterDate('2025-01-23', '2025-01-24');

      size = await collection.size().getInfo();
      console.log(`Landsat 9 images found: ${size}`);

      if (size === 0) {
        collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
          .filterBounds(fireLocation)
          .filterDate('2025-01-23', '2025-01-24');

        size = await collection.size().getInfo();
        console.log(`Landsat 8 images found: ${size}`);
      }
    }

    if (size === 0) {
      console.log("No satellite imagery available for January 23, 2025");
      console.log("<answer>C1</answer>");
      return;
    }

    // 3. Processing - Analyze smoke using aerosol/true color
    const image = collection.first();

    // Check if it's Sentinel-2 or Landsat
    const bandNames = await image.bandNames().getInfo();
    let aerosolBand, blueBand, redBand;

    if (bandNames.includes('B1')) { // Sentinel-2
      aerosolBand = 'B1'; // Aerosol band
      blueBand = 'B2';
      redBand = 'B4';
    } else { // Landsat
      aerosolBand = 'SR_B1'; // Coastal aerosol
      blueBand = 'SR_B2';
      redBand = 'SR_B4';
    }

    // 4. Calculate aerosol optical depth proxy at fire location and western extent
    const fireStats = await image.select(aerosolBand)
      .reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: fireLocation.buffer(5000),
        scale: 3000,
        maxPixels: 1e9
      }).getInfo();

    const westernStats = await image.select(aerosolBand)
      .reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: westernExtent.buffer(5000),
        scale: 3000,
        maxPixels: 1e9
      }).getInfo();

    const fireAerosol = fireStats[aerosolBand];
    const westernAerosol = westernStats[aerosolBand];

    console.log(`Fire location aerosol: ${fireAerosol}`);
    console.log(`50km west aerosol: ${westernAerosol}`);

    // 5. Validation & Final Answer
    if (fireAerosol === null || fireAerosol === undefined) {
      console.log("No valid pixels at fire location");
      console.log("<answer>C2</answer>");
      return;
    }

    if (westernAerosol === null || westernAerosol === undefined) {
      console.log("No valid data 50km westward - plume may not extend that far");
      console.log("<answer>A</answer>");
      return;
    }

    // Detect if smoke plume extends 50km west
    // If aerosol values at 50km west are elevated (relative to fire location)
    const aerosolRatio = westernAerosol / fireAerosol;

    console.log(`Aerosol ratio (west/fire): ${aerosolRatio.toFixed(2)}`);

    // If significant aerosol presence 50km west (>30% of fire location value)
    if (aerosolRatio > 0.3) {
      console.log("Smoke plume extends >= 50 km westward");
      console.log("<answer>B</answer>");
    } else {
      console.log("Smoke plume extends < 50 km westward");
      console.log("<answer>A</answer>");
    }

  } catch (error) {
    console.log(`Error: ${error.message}`);
    console.log("<answer>D</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
